{
  "name": "design-guardrail",
  "version": "0.1.0",
  "description": "Blocks Write and Edit on UI files that hardcode hex/rgb/hsl colors or px spacing and font values, and names the design token to use instead.",
  "author": {
    "name": "Joshua Small"
  },
  "license": "MIT",
  "keywords": [
    "design-system",
    "design-tokens",
    "css",
    "guardrail"
  ],
  "userConfig": {
    "enabled": {
      "type": "boolean",
      "title": "Enabled",
      "description": "Turn the design token guard on or off.",
      "default": true
    },
    "configFile": {
      "type": "string",
      "title": "Project config file",
      "description": "JSON file, relative to the project, whose keys override these options (enabled, tokensFile, extensions, ignore, allow, allowSvgColors, blockBashWrites, watchBash, maxReported).",
      "default": ".claude/guardrail-mods/design-guardrail.json"
    },
    "tokensFile": {
      "type": "string",
      "title": "Tokens file",
      "description": "Where the allowed design tokens live, relative to the project: a JSON tokens file (nested, $value or value leaves) or a CSS/SCSS/Less file of variables.",
      "default": "design-tokens.json"
    },
    "extensions": {
      "type": "string",
      "title": "UI file extensions",
      "description": "Comma-separated extensions the guard checks.",
      "default": ".css,.scss,.sass,.less,.tsx,.jsx,.vue,.html,.svelte,.astro"
    },
    "ignore": {
      "type": "string",
      "title": "Ignored paths",
      "description": "Comma-separated globs the guard skips, such as **/*.stories.tsx,legacy/**.",
      "default": ""
